// ============================================================================
// TSP_apb: APB4 register wrapper around TSP_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/TSP.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/TSP.md
// ============================================================================
module TSP_apb #(
  parameter logic [3:0] AXI_ID = 4'd12
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h7C0C0100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [27:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd28) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_keep_tsc;
  logic          c_pcr_en;
  logic [12:0]   c_pcr_pid;
  logic [31:0]   c_src_addr;
  logic [15:0]   c_pkts;
  logic [31:0]   c_outa_addr;
  logic [15:0]   c_outa_max;
  logic [31:0]   c_outb_addr;
  logic [15:0]   c_outb_max;
  logic [1:0]    c_slot;
  logic          c_odd;
  logic [31:0]   c_key0;
  logic [31:0]   c_key1;
  logic [31:0]   c_key2;
  logic [31:0]   c_key3;
  logic [12:0]   c_slot_pid;
  logic          c_slot_valid;
  logic [1:0]    c_slot_route;
  logic          c_start;
  logic          c_key_load;
  logic          c_slot_load;
  logic          c_busy;
  logic          c_key_busy;
  logic          c_err;
  logic [15:0]   c_a_cnt;
  logic [15:0]   c_b_cnt;
  logic [15:0]   c_desc_cnt;
  logic [15:0]   c_nokey_cnt;
  logic [15:0]   c_sync_cnt;
  logic [15:0]   c_drop_cnt;
  logic [15:0]   c_ovf_cnt;
  logic [15:0]   c_pkt_cnt;
  logic [31:0]   c_pcr_base;
  logic [9:0]    c_pcr_ext;
  logic [31:0]   c_pcr_local;
  logic          c_done;
  logic          c_err_irq;
  logic          c_nokey;
  logic          c_sync;
  logic          c_pcr;
  logic          c_ovf;
  TSP_top #(.AXI_ID(AXI_ID)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .keep_tsc(c_keep_tsc),
    .pcr_en(c_pcr_en),
    .pcr_pid(c_pcr_pid),
    .src_addr(c_src_addr),
    .pkts(c_pkts),
    .outa_addr(c_outa_addr),
    .outa_max(c_outa_max),
    .outb_addr(c_outb_addr),
    .outb_max(c_outb_max),
    .slot(c_slot),
    .odd(c_odd),
    .key0(c_key0),
    .key1(c_key1),
    .key2(c_key2),
    .key3(c_key3),
    .slot_pid(c_slot_pid),
    .slot_valid(c_slot_valid),
    .slot_route(c_slot_route),
    .start(c_start),
    .key_load(c_key_load),
    .slot_load(c_slot_load),
    .busy(c_busy),
    .key_busy(c_key_busy),
    .err(c_err),
    .a_cnt(c_a_cnt),
    .b_cnt(c_b_cnt),
    .desc_cnt(c_desc_cnt),
    .nokey_cnt(c_nokey_cnt),
    .sync_cnt(c_sync_cnt),
    .drop_cnt(c_drop_cnt),
    .ovf_cnt(c_ovf_cnt),
    .pkt_cnt(c_pkt_cnt),
    .pcr_base(c_pcr_base),
    .pcr_ext(c_pcr_ext),
    .pcr_local(c_pcr_local),
    .done(c_done),
    .err_irq(c_err_irq),
    .nokey(c_nokey),
    .sync(c_sync),
    .pcr(c_pcr),
    .ovf(c_ovf),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [5:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [1:0] r_CTRL;   // 12'h014 CTRL
  logic [12:0] r_PCR_PID;   // 12'h018 PCR_PID
  logic [31:0] r_SRC_ADDR;   // 12'h01C SRC_ADDR
  logic [15:0] r_PKTS;   // 12'h020 PKTS
  logic [31:0] r_OUTA_ADDR;   // 12'h024 OUTA_ADDR
  logic [15:0] r_OUTA_MAX;   // 12'h028 OUTA_MAX
  logic [31:0] r_OUTB_ADDR;   // 12'h02C OUTB_ADDR
  logic [15:0] r_OUTB_MAX;   // 12'h030 OUTB_MAX
  logic [2:0] r_SLOT_SEL;   // 12'h034 SLOT_SEL
  logic [31:0] r_KEY0;   // 12'h038 KEY0
  logic [31:0] r_KEY1;   // 12'h03C KEY1
  logic [31:0] r_KEY2;   // 12'h040 KEY2
  logic [31:0] r_KEY3;   // 12'h044 KEY3
  logic [15:0] r_SLOT_CFG;   // 12'h048 SLOT_CFG
  logic [2:0] p_CMD;   // 12'h04C CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 2'h0;
      r_PCR_PID <= 13'h0;
      r_SRC_ADDR <= 32'h0;
      r_PKTS <= 16'h0;
      r_OUTA_ADDR <= 32'h0;
      r_OUTA_MAX <= 16'h0;
      r_OUTB_ADDR <= 32'h0;
      r_OUTB_MAX <= 16'h0;
      r_SLOT_SEL <= 3'h0;
      r_KEY0 <= 32'h0;
      r_KEY1 <= 32'h0;
      r_KEY2 <= 32'h0;
      r_KEY3 <= 32'h0;
      r_SLOT_CFG <= 16'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[5:0] & wmask[5:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[5:0]) | (PWDATA[5:0] & wmask[5:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[6]) r_PCR_PID <= (r_PCR_PID & ~wmask[12:0]) | (PWDATA[12:0] & wmask[12:0]);
      if (wr && hit[7]) r_SRC_ADDR <= (r_SRC_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_PKTS <= (r_PKTS & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[9]) r_OUTA_ADDR <= (r_OUTA_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_OUTA_MAX <= (r_OUTA_MAX & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[11]) r_OUTB_ADDR <= (r_OUTB_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[12]) r_OUTB_MAX <= (r_OUTB_MAX & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[13]) r_SLOT_SEL <= (r_SLOT_SEL & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[14]) r_KEY0 <= (r_KEY0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[15]) r_KEY1 <= (r_KEY1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[16]) r_KEY2 <= (r_KEY2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[17]) r_KEY3 <= (r_KEY3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[18]) r_SLOT_CFG <= (r_SLOT_CFG & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      p_CMD <= (wr && hit[19]) ? PWDATA[2:0] & wmask[2:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_keep_tsc = r_CTRL[0:0];
  assign c_pcr_en = r_CTRL[1:1];
  assign c_pcr_pid = r_PCR_PID[12:0];
  assign c_src_addr = r_SRC_ADDR[31:0];
  assign c_pkts = r_PKTS[15:0];
  assign c_outa_addr = r_OUTA_ADDR[31:0];
  assign c_outa_max = r_OUTA_MAX[15:0];
  assign c_outb_addr = r_OUTB_ADDR[31:0];
  assign c_outb_max = r_OUTB_MAX[15:0];
  assign c_slot = r_SLOT_SEL[1:0];
  assign c_odd = r_SLOT_SEL[2:2];
  assign c_key0 = r_KEY0[31:0];
  assign c_key1 = r_KEY1[31:0];
  assign c_key2 = r_KEY2[31:0];
  assign c_key3 = r_KEY3[31:0];
  assign c_slot_pid = r_SLOT_CFG[12:0];
  assign c_slot_valid = r_SLOT_CFG[13:13];
  assign c_slot_route = r_SLOT_CFG[15:14];
  assign c_start = p_CMD[0:0];
  assign c_key_load = p_CMD[1:1];
  assign c_slot_load = p_CMD[2:2];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
    irq_set[1] = c_err_irq;
    irq_set[2] = c_nokey;
    irq_set[3] = c_sync;
    irq_set[4] = c_pcr;
    irq_set[5] = c_ovf;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_PCR_PID);
      10'd7: apb_rdata = 32'(r_SRC_ADDR);
      10'd8: apb_rdata = 32'(r_PKTS);
      10'd9: apb_rdata = 32'(r_OUTA_ADDR);
      10'd10: apb_rdata = 32'(r_OUTA_MAX);
      10'd11: apb_rdata = 32'(r_OUTB_ADDR);
      10'd12: apb_rdata = 32'(r_OUTB_MAX);
      10'd13: apb_rdata = 32'(r_SLOT_SEL);
      10'd18: apb_rdata = 32'(r_SLOT_CFG);
      10'd20: apb_rdata = 32'({c_err, c_key_busy, c_busy});
      10'd21: apb_rdata = 32'({c_b_cnt, c_a_cnt});
      10'd22: apb_rdata = 32'({c_nokey_cnt, c_desc_cnt});
      10'd23: apb_rdata = 32'({c_drop_cnt, c_sync_cnt});
      10'd24: apb_rdata = 32'({c_pkt_cnt, c_ovf_cnt});
      10'd25: apb_rdata = 32'({c_pcr_base});
      10'd26: apb_rdata = 32'({c_pcr_ext});
      10'd27: apb_rdata = 32'({c_pcr_local});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
